prog = '''
def transform(grid):
    import numpy as np
    from scipy import ndimage
    g = np.array(grid)
    H, W = g.shape
    objs = []
    for c in np.unique(g):
        if c == 0: continue
        lab, n = ndimage.label(g == c, structure=np.ones((3, 3)))
        for k in range(1, n + 1):
            m = lab == k
            ys, xs = np.nonzero(m)
            objs.append((int(c), m, ys.min(), ys.max(), xs.min(), xs.max()))
    objs.sort(key=lambda o: o[2])
    up, lo = objs[0], objs[1]
    sub = np.where(up[1][up[2]:up[3]+1, up[4]:up[5]+1], up[0], 0)
    out = g.copy()
    out[lo[1]] = 0
    col_overlap = not (lo[5] < up[4] or lo[4] > up[5])
    if col_overlap:
        # vertical: mirror vertically, place directly below upper, same columns
        img = sub[::-1, :]
        top = up[3] + 1
        for r in range(img.shape[0]):
            for c2 in range(img.shape[1]):
                rr, cc = top + r, up[4] + c2
                if 0 <= rr < H and 0 <= cc < W and img[r][c2]:
                    out[rr][cc] = int(img[r][c2])
    else:
        # horizontal: mirror horizontally about the facing edge, same rows
        side = 1 if (lo[4] + lo[5]) / 2 > (up[4] + up[5]) / 2 else -1
        if side == 1:
            axis = up[5] + 0.5   # right edge
        else:
            axis = up[4] - 0.5   # left edge
        for r in range(sub.shape[0]):
            for c2 in range(sub.shape[1]):
                if sub[r][c2]:
                    cc = int(round(2 * axis - (up[4] + c2)))
                    rr = up[2] + r
                    if 0 <= rr < H and 0 <= cc < W:
                        out[rr][cc] = int(sub[r][c2])
    return out.tolist()
'''
